import{_ as d,o as r,c as e,a3 as a}from"./chunks/framework.CTwvqqO-.js";const h=JSON.parse('{"title":"スクラムバン用語辞典","description":"スクラムバン(Scrumban)は、スクラムの反復的構造とカンバンのフロー管理・WIP制限を組み合わせ、柔軟かつ効率的に作業を管理するハイブリッドアジャイル方法論です。","frontmatter":{"title":"スクラムバン用語辞典","description":"スクラムバン(Scrumban)は、スクラムの反復的構造とカンバンのフロー管理・WIP制限を組み合わせ、柔軟かつ効率的に作業を管理するハイブリッドアジャイル方法論です。","head":[["meta",{"name":"keywords","content":"スクラムバン, Scrumban, スクラムバン紹介, スクラムバンの概念, スクラムバンとは, Scrumban紹介, Scrumban概念, スクラムとカンバンの違い, スクラム vs カンバン, アジャイル方法論, アジャイルフレームワーク, カンバン方法論, スクラム方法論, スクラムバンプロセス, スクラムバン運用ガイド, スクラムバンボード, WIP制限, ワークフロー管理, カンバンボードの使い方, スクラムバンのメリット, スクラムバンの特徴, スクラムバンの効果, スクラムバン活用事例, スクラムバン導入効果, スクラムバン Jira設定, スクラムバンボードテンプレート, Scrumbanツール, スクラムバンコラボレーションツール, スクラムバンワークフロー, アジャイルプロジェクト管理, 業務効率化方法論, 反復的作業管理, ボトルネック解消"}],["meta",{"property":"og:title","content":"スクラムバン"}],["meta",{"property":"og:description","content":"スクラムバン(Scrumban)は、スクラムの反復的構造とカンバンのフロー管理・WIP制限を組み合わせ、柔軟かつ効率的に作業を管理するハイブリッドアジャイル方法論です。"}],["meta",{"property":"og:image","content":"https://empasy.io/docs/images/favicon.png"}],["meta",{"property":"og:url","content":"https://empasy.io/agile/glossaryOfTerms.html"}],["link",{"rel":"canonical","href":"https://empasy.io/docs/ja/agile/glossaryOfTerms.html"}]],"sort":1000},"headers":[],"relativePath":"ja/agile/glossaryOfTerms.md","filePath":"ja/agile/glossaryOfTerms.md","lastUpdated":1788702614000}'),n={name:"ja/agile/glossaryOfTerms.md"};function o(s,t,i,m,l,c){return r(),e("div",null,[...t[0]||(t[0]=[a('<h2 id="📚-スクラムバン用語辞典" tabindex="-1">📚 スクラムバン用語辞典 <a class="header-anchor" href="#📚-スクラムバン用語辞典" aria-label="Permalink to “📚 スクラムバン用語辞典”">​</a></h2><table tabindex="0"><thead><tr><th>カテゴリ</th><th>韓国語</th><th>英語</th><th>略語</th><th>説明</th></tr></thead><tbody><tr><td>基本概念</td><td>スクラムバン(스크럼반)</td><td>Scrumban</td><td>-</td><td>スクラム(Scrum)とカンバン(Kanban)のメリットを組み合わせたアジャイルプロジェクト管理フレームワーク</td></tr><tr><td>基本概念</td><td>スクラム(스크럼)</td><td>Scrum</td><td>-</td><td>反復(iteration)とスプリント中心のアジャイル開発方法論</td></tr><tr><td>基本概念</td><td>カンバン(칸반)</td><td>Kanban</td><td>-</td><td>ワークフローを視覚化し、進行中の作業(WIP)を制限する方式のプロジェクト管理手法</td></tr><tr><td>基本概念</td><td>アジャイル(애자일)</td><td>Agile</td><td>-</td><td>柔軟かつ反復的な方式で製品を開発する哲学および方法論の集合</td></tr><tr><td>作業単位</td><td>作業項目(작업 항목)</td><td>Work Item</td><td>-</td><td>チームが遂行すべき具体的な作業の単位</td></tr><tr><td>作業単位</td><td>ユーザーストーリー(사용자 스토리)</td><td>User Story</td><td>-</td><td>ユーザーの要件を簡単なストーリー形式で表現した作業単位</td></tr><tr><td>作業単位</td><td>タスク(태스크)</td><td>Task</td><td>-</td><td>ユーザーストーリーや作業をより小さな単位に分けた詳細な実行項目</td></tr><tr><td>ボード構成</td><td>バックログ(백로그)</td><td>Backlog</td><td>-</td><td>まだ着手していないすべての作業項目のリスト</td></tr><tr><td>ボード構成</td><td>準備完了(준비됨)</td><td>Ready</td><td>-</td><td>着手する準備が完了した作業項目の状態</td></tr><tr><td>ボード構成</td><td>進行中(진행 중)</td><td>In Progress</td><td>-</td><td>現在作業が進行している状態</td></tr><tr><td>ボード構成</td><td>レビュー中(검토 중)</td><td>Review</td><td>-</td><td>完了した作業が品質レビューを待っている状態</td></tr><tr><td>ボード構成</td><td>完了(완료)</td><td>Done</td><td>-</td><td>すべてのレビューを通過し、デプロイの準備ができた状態</td></tr><tr><td>運用ルール</td><td>進行中作業の制限(진행 중 작업 제한)</td><td>Work In Progress Limit</td><td>WIP</td><td>同時に進行できる作業項目の最大数</td></tr><tr><td>運用ルール</td><td>リードタイム(리드 타임)</td><td>Lead Time</td><td>-</td><td>作業依頼が発生した時点から完了するまでにかかった全体の時間</td></tr><tr><td>運用ルール</td><td>サイクルタイム(사이클 타임)</td><td>Cycle Time</td><td>-</td><td>作業に着手した時点から完了するまでにかかった時間</td></tr><tr><td>運用ルール</td><td>フロー効率(플로우 효율성)</td><td>Flow Efficiency</td><td>-</td><td>作業進行時間に対する実際に作業に消費された時間の割合</td></tr><tr><td>イベント</td><td>デイリースタンドアップ(데일리 스탠드업)</td><td>Daily Stand-up</td><td>-</td><td>毎日短時間で行われるチームの進捗状況共有ミーティング</td></tr><tr><td>イベント</td><td>スプリント計画会議(스프린트 계획 회의)</td><td>Sprint Planning Meeting</td><td>-</td><td>次のスプリントで実行する作業を計画する会議</td></tr><tr><td>イベント</td><td>レビュー会議(리뷰 회의)</td><td>Review Meeting</td><td>-</td><td>完了した作業をレビューし、フィードバックを受ける会議</td></tr><tr><td>イベント</td><td>振り返り(회고)</td><td>Retrospective</td><td>-</td><td>チームが一定の周期で行うプロセス改善会議</td></tr><tr><td>測定指標</td><td>バーンダウンチャート(번다운 차트)</td><td>Burndown Chart</td><td>-</td><td>残りの作業量を時間経過に沿って視覚化したチャート</td></tr><tr><td>測定指標</td><td>累積フロー図(누적 흐름도)</td><td>Cumulative Flow Diagram</td><td>CFD</td><td>作業状態別の累積項目の変化を視覚化し、ボトルネックを把握するチャート</td></tr></tbody></table><hr>',3)])])}const g=d(n,[["render",o]]);export{h as __pageData,g as default};
